css:
.esg-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #e8f5e9 0%, #e0f2f1 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.esg-sim-header {
    background: linear-gradient(135deg, #1b5e20 0%, #2e7d32 50%, #00695c 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 20px;
    box-shadow: 0 8px 16px rgba(0,0,0,0.15);
    text-align: center;
}

.esg-sim-header h1 { margin: 0 0 5px 0; font-size: 1.8rem; }
.esg-sim-header p { margin: 0; opacity: 0.9; font-size: 0.95rem; }

.esg-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #555;
}

.esg-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.esg-sim-status-card {
    background: white;
    border-radius: 12px;
    padding: 18px 14px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.2s ease;
}

.esg-sim-status-card:hover { transform: translateY(-3px); }
.esg-sim-status-card .label { color: #666; font-size: 0.78rem; text-transform: uppercase; margin-bottom: 6px; letter-spacing: 0.5px; }
.esg-sim-status-card .value { font-size: 1.7rem; font-weight: 700; color: #333; }
.esg-sim-card-highlight .value { color: #1b5e20; }
.esg-sim-card-env { border-left: 4px solid #4caf50; }
.esg-sim-card-social { border-left: 4px solid #2196f3; }
.esg-sim-card-gov { border-left: 4px solid #ff9800; }

.esg-sim-briefing {
    background: #fff;
    border-left: 5px solid #1b5e20;
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.esg-sim-briefing h4 { color: #1b5e20; margin: 0 0 10px 0; }
.esg-sim-briefing p { margin: 0; color: #555; line-height: 1.5; }

.esg-sim-event {
    background: #fff3e0;
    border-left: 5px solid #e65100;
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 20px;
}

.esg-sim-event h4 { color: #e65100; margin: 0 0 10px 0; }
.esg-sim-event p { margin: 0 0 5px 0; color: #555; }
.esg-sim-event-impact { font-weight: 600; color: #bf360c; }

.esg-sim-controls {
    background: white;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.esg-sim-controls h3 { color: #1b5e20; margin: 0 0 20px 0; font-size: 1.2rem; }

.esg-sim-slider-group {
    margin-bottom: 18px;
}

.esg-sim-slider-group label {
    display: block;
    font-weight: 600;
    color: #444;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.esg-sim-slider-group input[type="range"] {
    width: calc(100% - 70px);
    display: inline-block;
    vertical-align: middle;
    accent-color: #1b5e20;
}

.esg-sim-slider-value {
    display: inline-block;
    width: 60px;
    text-align: right;
    font-weight: 700;
    color: #1b5e20;
    font-size: 0.95rem;
}

.esg-sim-select-group {
    margin-bottom: 18px;
}

.esg-sim-select-group label {
    display: block;
    font-weight: 600;
    color: #444;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.esg-sim-select-group select {
    max-width: 300px;
    width: 100%;
    background-color: #ffffff;
    color: #1b5e20;
    border: 1px solid #1b5e20;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.95rem;
}

.esg-sim-select-group select option {
    background-color: #ffffff;
    color: #1b5e20;
}

.esg-sim-budget-bar {
    background: #f5f5f5;
    border-radius: 8px;
    padding: 12px 15px;
    margin-bottom: 20px;
    font-size: 0.9rem;
    color: #555;
}

.esg-sim-progress-track {
    background: #e0e0e0;
    border-radius: 6px;
    height: 10px;
    margin-top: 8px;
    overflow: hidden;
}

.esg-sim-progress-fill {
    background: linear-gradient(90deg, #4caf50, #1b5e20);
    height: 100%;
    border-radius: 6px;
    transition: width 0.3s ease;
}

.esg-sim-submit-btn {
    background: linear-gradient(135deg, #2e7d32, #1b5e20) !important;
    border: none !important;
    color: white !important;
    font-size: 1.1rem;
    padding: 12px;
    border-radius: 10px !important;
}

.esg-sim-submit-btn:hover {
    background: linear-gradient(135deg, #388e3c, #2e7d32) !important;
}

.esg-sim-charts-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}

.esg-sim-chart-box {
    background: white;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.esg-sim-chart-box h4 { color: #333; margin: 0 0 15px 0; font-size: 1rem; }
.esg-sim-chart-box canvas { max-height: 280px; }

.esg-sim-history {
    background: white;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.esg-sim-history h4 { color: #333; margin: 0 0 15px 0; }

.esg-sim-summary {
    background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%);
    border: 2px solid #2e7d32;
    border-radius: 15px;
    padding: 30px;
    margin-top: 20px;
}

.esg-sim-summary h3 { color: #1b5e20; text-align: center; margin: 0 0 20px 0; }
.esg-sim-summary p { line-height: 1.6; color: #333; }

@media (max-width: 768px) {
    .esg-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .esg-sim-charts-row { grid-template-columns: 1fr; }
    .esg-sim-header h1 { font-size: 1.3rem; }
}

