(function() {
    'use strict';

    // Number of narrative years authored in the translation dictionary
    // (round1_title..round5_title). Period-end detection uses state.maxPeriods,
    // so the game mechanic is decoupled from this content constant.
    var AUTHORED_ROUNDS = 5;

    // Baseline (year-0) KPIs, kept consistent with the model formulas so the
    // "(from X)" deltas in the summary are meaningful:
    //   financialScore = round(ebitda/20*100) = round(14.2/20*100) = 71
    //   composite      = round(25*.35 + 30*.35 + 20*.20 + 71*.10) = 30
    //   msciRating     = _getMsciRating(30) = 'B'
    var START = {
        env: 25, social: 30, gov: 20,
        ebitda: 14.2, financial: 71, composite: 30, rating: 'B'
    };

    // Event mechanics only — all display text lives in getTranslations()
    // under event{index}_name / event{index}_desc.
    var EVENTS = [
        { pillar: 'social',        threshold: 50, penaltyLow: 8,  penaltyHigh: 3, affectsFinance: false },
        { pillar: 'environmental', threshold: 45, penaltyLow: 6,  penaltyHigh: 2, affectsFinance: true },
        { pillar: 'governance',    threshold: 40, penaltyLow: 7,  penaltyHigh: 2, affectsFinance: false },
        { pillar: 'environmental', threshold: 50, penaltyLow: 5,  penaltyHigh: 1, affectsFinance: true },
        { pillar: 'environmental', threshold: 55, penaltyLow: 9,  penaltyHigh: 3, affectsFinance: false },
        { pillar: 'environmental', threshold: 45, penaltyLow: 6,  penaltyHigh: 2, affectsFinance: false },
        { pillar: 'governance',    threshold: 50, penaltyLow: 10, penaltyHigh: 3, affectsFinance: true },
        { pillar: 'environmental', threshold: 55, penaltyLow: 0,  penaltyHigh: 0, isOpportunity: true, bonusBudget: 8, bonusScore: 3 },
        { pillar: 'composite',     threshold: 55, penaltyLow: 0,  penaltyHigh: 0, isOpportunity: true, bonusBudget: 5, bonusScore: 2 },
        { pillar: 'social',        threshold: 65, penaltyLow: 0,  penaltyHigh: 0, isOpportunity: true, bonusBudget: 3, bonusScore: 5 }
    ];

    class ESGBoardroomAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'ESG Boardroom: Triple Bottom Line Strategy';
            this.version = '1.2.0';
            this._wired = false;
        }

        // ── Framework helpers ────────────────────────────────────────────────
        _t(key, vars) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                return window.mySimulation.t(key, vars);
            }
            return key;
        }

        _getState() {
            return (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state : null;
        }

        // ── Lifecycle ────────────────────────────────────────────────────────
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    budget: 20,
                    envScore: START.env,
                    socialScore: START.social,
                    govScore: START.gov,
                    ebitdaMargin: START.ebitda,
                    financialScore: START.financial,
                    composite: START.composite,
                    msciRating: START.rating,
                    totalEnvInvest: 0,
                    totalSocialInvest: 0,
                    totalGovInvest: 0,
                    crisisCount: 0,
                    envHistory: [],
                    socialHistory: [],
                    govHistory: [],
                    compositeHistory: [],
                    ebitdaHistory: [],
                    budgetHistory: [],
                    eventLog: [],
                    usedEventIndices: [],
                    lastEvent: null
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    envInvest: 5,
                    socialInvest: 5,
                    govInvest: 3,
                    strategy: 'balanced'
                };
            }
            this._wireEvents();
            this._updateBriefing(state);
            this._attachSliderListeners();
        }

        /**
         * Subscribe once to framework lifecycle + language events. This replaces
         * the previous setTimeout-based UI sequencing and keeps calculateResults
         * free of DOM side effects (so the competition-mode preview, which runs
         * calculateResults on a cloned state, no longer leaks event panels).
         */
        _wireEvents() {
            if (this._wired) return;
            if (!window.mySimulation || !window.mySimulation.eventBus) return;
            var self = this;

            window.mySimulation.eventBus.on('period:submitted', function(result) {
                var state = self._getState();
                if (!state) return;
                self._renderEventPanel(state);
                self._updateBriefing(state);
                self._updateBudgetDisplay();
                if (result && result.complete) self._showFinalSummary(state);
            });

            // Re-render language-dependent dynamic panels when the user switches
            // language (vcI18n dispatches this DOM event).
            document.addEventListener('express:langchanged', function() {
                var state = self._getState();
                if (!state) return;
                self._updateBriefing(state);
                var panel = document.getElementById('eventPanel');
                if (panel && panel.style.display !== 'none' && state.domainState.lastEvent) {
                    self._renderEventPanel(state);
                }
                var summary = document.getElementById('summaryPanel');
                if (summary && summary.style.display !== 'none') {
                    self._showFinalSummary(state);
                }
            });

            this._wired = true;
        }

        _attachSliderListeners() {
            var self = this;
            var sliders = ['envInvestInput', 'socialInvestInput', 'govInvestInput'];
            sliders.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() { self._updateBudgetDisplay(); });
                }
            });
            this._updateBudgetDisplay();
        }

        _updateBudgetDisplay() {
            var envEl = document.getElementById('envInvestInput');
            var socEl = document.getElementById('socialInvestInput');
            var govEl = document.getElementById('govInvestInput');
            if (!envEl || !socEl || !govEl) return;
            var env = parseInt(envEl.value) || 0;
            var soc = parseInt(socEl.value) || 0;
            var gov = parseInt(govEl.value) || 0;
            var total = env + soc + gov;
            var st = this._getState();
            var budget = st ? (st.domainState.budget || 20) : 20;

            var envVal = document.getElementById('envInvestValue');
            var socVal = document.getElementById('socialInvestValue');
            var govVal = document.getElementById('govInvestValue');
            var totalEl = document.getElementById('totalSpendingDisplay');
            var budgetEl = document.getElementById('budgetLimitDisplay');
            var barEl = document.getElementById('budgetProgressBar');

            if (envVal) envVal.textContent = '$' + env + 'M';
            if (socVal) socVal.textContent = '$' + soc + 'M';
            if (govVal) govVal.textContent = '$' + gov + 'M';
            if (totalEl) totalEl.textContent = '$' + total + 'M';
            if (budgetEl) budgetEl.textContent = '$' + Math.round(budget) + 'M';
            if (barEl) {
                var pct = Math.min(100, (total / budget) * 100);
                barEl.style.width = pct + '%';
                barEl.style.background = total > budget
                    ? 'linear-gradient(90deg, #e53935, #c62828)'
                    : 'linear-gradient(90deg, #4caf50, #1b5e20)';
            }
        }

        _updateBriefing(state) {
            var period = (state.currentPeriod || 1);
            var maxP = state.maxPeriods || AUTHORED_ROUNDS;
            if (period > maxP) period = maxP;
            // Only authored years have narrative text.
            if (period > AUTHORED_ROUNDS) period = AUTHORED_ROUNDS;
            if (period < 1) period = 1;
            var titleEl = document.getElementById('roundTitle');
            var descEl = document.getElementById('roundDescription');
            if (titleEl) titleEl.textContent = this._t('round' + period + '_title');
            if (descEl) descEl.textContent = this._t('round' + period + '_desc');
        }

        _pickEvent(state) {
            var used = state.domainState.usedEventIndices || [];
            var available = [];
            for (var i = 0; i < EVENTS.length; i++) {
                if (used.indexOf(i) === -1) available.push(i);
            }
            if (available.length === 0) {
                state.domainState.usedEventIndices = [];
                available = [];
                for (var j = 0; j < EVENTS.length; j++) available.push(j);
            }
            var pick = available[Math.floor(Math.random() * available.length)];
            state.domainState.usedEventIndices.push(pick);
            return pick;
        }

        _getMsciRating(composite) {
            if (composite >= 80) return 'AAA';
            if (composite >= 70) return 'AA';
            if (composite >= 60) return 'A';
            if (composite >= 50) return 'BBB';
            if (composite >= 40) return 'BB';
            if (composite >= 30) return 'B';
            return 'CCC';
        }

        validateDecisions(decisions) {
            var envEl = document.getElementById('envInvestInput');
            var socEl = document.getElementById('socialInvestInput');
            var govEl = document.getElementById('govInvestInput');
            var strEl = document.getElementById('strategyInput');

            if (envEl) decisions.envInvest = parseInt(envEl.value) || 0;
            if (socEl) decisions.socialInvest = parseInt(socEl.value) || 0;
            if (govEl) decisions.govInvest = parseInt(govEl.value) || 0;
            if (strEl) decisions.strategy = strEl.value;

            var total = decisions.envInvest + decisions.socialInvest + decisions.govInvest;
            var st = this._getState();
            var budget = (st && st.domainState.budget) ? st.domainState.budget : 20;

            if (total > budget) {
                window.mySimulation.uiManager.showNotification(this._t('budget_exceeded'), 'warning');
                return false;
            }
            if (total === 0) {
                window.mySimulation.uiManager.showNotification(this._t('zero_spending'), 'warning');
                return false;
            }
            return true;
        }

        /**
         * PURE calculation: mutates only the passed `state` (real or a preview
         * clone) and returns a results object. No DOM access, no timers — all
         * rendering happens in _renderEventPanel / _showFinalSummary, driven by
         * the framework's period:submitted event.
         */
        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var totalSpend = d.envInvest + d.socialInvest + d.govInvest;

            var envMult = 1.0;
            var socMult = 1.0;
            var govMult = 1.0;
            if (d.strategy === 'environmental') { envMult = 1.3; socMult = 0.85; govMult = 0.85; }
            else if (d.strategy === 'social') { socMult = 1.3; envMult = 0.85; govMult = 0.85; }
            else if (d.strategy === 'financial') { envMult = 0.7; socMult = 0.7; govMult = 0.7; }

            var envGain = d.envInvest * (1.2 + Math.random() * 0.6) * envMult * (1 - ds.envScore / 150);
            var socGain = d.socialInvest * (1.0 + Math.random() * 0.5) * socMult * (1 - ds.socialScore / 150);
            var govGain = d.govInvest * (1.5 + Math.random() * 0.7) * govMult * (1 - ds.govScore / 150);

            ds.envScore = Math.min(100, Math.round((ds.envScore + envGain) * 10) / 10);
            ds.socialScore = Math.min(100, Math.round((ds.socialScore + socGain) * 10) / 10);
            ds.govScore = Math.min(100, Math.round((ds.govScore + govGain) * 10) / 10);

            var idx = this._pickEvent(state);
            var evt = EVENTS[idx];
            var le = { index: idx, isOpportunity: !!evt.isOpportunity, pillar: evt.pillar,
                       affectsFinance: !!evt.affectsFinance };
            var eventMitigated = false;

            if (evt.isOpportunity) {
                var checkScore = 0;
                if (evt.pillar === 'environmental') checkScore = ds.envScore;
                else if (evt.pillar === 'social') checkScore = ds.socialScore;
                else if (evt.pillar === 'governance') checkScore = ds.govScore;
                else checkScore = ds.envScore * 0.35 + ds.socialScore * 0.35 + ds.govScore * 0.2 + ds.financialScore * 0.1;

                if (checkScore >= evt.threshold) {
                    ds.budget += evt.bonusBudget;
                    ds.envScore = Math.min(100, ds.envScore + evt.bonusScore);
                    ds.socialScore = Math.min(100, ds.socialScore + evt.bonusScore);
                    le.impactType = 'opp_captured';
                    le.bonusBudget = evt.bonusBudget;
                    le.bonusScore = evt.bonusScore;
                    eventMitigated = true;
                } else {
                    le.impactType = 'opp_missed';
                    le.threshold = evt.threshold;
                }
            } else {
                var relevantScore = 0;
                if (evt.pillar === 'environmental') relevantScore = ds.envScore;
                else if (evt.pillar === 'social') relevantScore = ds.socialScore;
                else relevantScore = ds.govScore;

                if (relevantScore >= evt.threshold) {
                    var penalty = evt.penaltyHigh;
                    if (evt.pillar === 'environmental') ds.envScore = Math.max(0, ds.envScore - penalty);
                    else if (evt.pillar === 'social') ds.socialScore = Math.max(0, ds.socialScore - penalty);
                    else ds.govScore = Math.max(0, ds.govScore - penalty);
                    le.impactType = 'crisis_mitigated';
                    le.penalty = penalty;
                    eventMitigated = true;
                } else {
                    var penaltyFull = evt.penaltyLow;
                    if (evt.pillar === 'environmental') ds.envScore = Math.max(0, ds.envScore - penaltyFull);
                    else if (evt.pillar === 'social') ds.socialScore = Math.max(0, ds.socialScore - penaltyFull);
                    else ds.govScore = Math.max(0, ds.govScore - penaltyFull);
                    ds.crisisCount += 1;
                    if (evt.affectsFinance) ds.ebitdaMargin = Math.max(5, ds.ebitdaMargin - 0.8);
                    le.impactType = 'crisis_full';
                    le.penalty = penaltyFull;
                }
            }

            le.mitigated = eventMitigated;
            ds.lastEvent = le;
            ds.eventLog.push({ index: idx, mitigated: eventMitigated });

            var ebitdaDrag = (totalSpend / 60) * 1.2;
            var esgPremium = 0;
            var avgEsg = (ds.envScore + ds.socialScore + ds.govScore) / 3;
            if (avgEsg > 50) esgPremium = (avgEsg - 50) * 0.02;
            if (d.strategy === 'financial') { ebitdaDrag *= 0.5; esgPremium *= 0.5; }

            ds.ebitdaMargin = Math.round((ds.ebitdaMargin - ebitdaDrag + esgPremium + 0.3) * 10) / 10;
            ds.ebitdaMargin = Math.max(5, Math.min(25, ds.ebitdaMargin));
            ds.financialScore = Math.round(Math.min(100, Math.max(0, (ds.ebitdaMargin / 20) * 100)));

            ds.composite = Math.round(ds.envScore * 0.35 + ds.socialScore * 0.35 + ds.govScore * 0.20 + ds.financialScore * 0.10);
            ds.msciRating = this._getMsciRating(ds.composite);

            ds.totalEnvInvest += d.envInvest;
            ds.totalSocialInvest += d.socialInvest;
            ds.totalGovInvest += d.govInvest;

            ds.envHistory.push(ds.envScore);
            ds.socialHistory.push(ds.socialScore);
            ds.govHistory.push(ds.govScore);
            ds.compositeHistory.push(ds.composite);
            ds.ebitdaHistory.push(ds.ebitdaMargin);
            ds.budgetHistory.push(ds.budget);

            var baseBudget = 20;
            if (ds.ebitdaMargin > 14) baseBudget += 5;
            baseBudget -= ds.crisisCount * 2.5;
            ds.budget = Math.max(8, Math.round(baseBudget * 10) / 10);
            ds.crisisCount = 0;

            return {
                period: state.currentPeriod,
                envInvest: d.envInvest,
                socialInvest: d.socialInvest,
                govInvest: d.govInvest,
                strategy: d.strategy,
                envScore: ds.envScore,
                socialScore: ds.socialScore,
                govScore: ds.govScore,
                composite: ds.composite,
                msciRating: ds.msciRating,
                ebitdaMargin: ds.ebitdaMargin,
                eventIndex: idx,
                eventIsOpportunity: !!evt.isOpportunity,
                eventMitigated: eventMitigated
            };
        }

        // ── Rendering (DOM) — called from event handlers, never calculate ─────
        _buildImpactText(le) {
            switch (le.impactType) {
                case 'opp_captured':
                    return this._t('impact_opp_captured', { bonusBudget: le.bonusBudget, bonusScore: le.bonusScore });
                case 'opp_missed':
                    return this._t('impact_opp_missed', { threshold: le.threshold });
                case 'crisis_mitigated':
                    return this._t('impact_crisis_mitigated', { pillar: this._t('pillar_' + le.pillar), penalty: le.penalty });
                case 'crisis_full':
                    return this._t('impact_crisis_full', { pillar: this._t('pillar_' + le.pillar), penalty: le.penalty })
                         + (le.affectsFinance ? this._t('impact_finance_suffix') : '');
                default:
                    return '';
            }
        }

        _renderEventPanel(state) {
            var le = state.domainState.lastEvent;
            if (!le) return;
            var panel = document.getElementById('eventPanel');
            var titleEl = document.getElementById('eventTitle');
            var descEl = document.getElementById('eventDescription');
            var impactEl = document.getElementById('eventImpact');
            if (!panel) return;
            panel.style.display = 'block';
            if (titleEl) titleEl.textContent = (le.isOpportunity ? '🌟 ' : '⚠️ ') + this._t('event' + le.index + '_name');
            if (descEl) descEl.textContent = this._t('event' + le.index + '_desc');
            if (impactEl) impactEl.textContent = this._buildImpactText(le);
        }

        _showFinalSummary(state) {
            var ds = state.domainState;
            var panel = document.getElementById('summaryPanel');
            var content = document.getElementById('summaryContent');
            if (!panel || !content) return;

            var envGain = Math.round(ds.envScore - START.env);
            var socGain = Math.round(ds.socialScore - START.social);
            var govGain = Math.round(ds.govScore - START.gov);

            var rating = ds.msciRating;
            var ratingMsg;
            if (rating === 'AAA' || rating === 'AA') ratingMsg = this._t('rating_msg_leader');
            else if (rating === 'A' || rating === 'BBB') ratingMsg = this._t('rating_msg_strong');
            else if (rating === 'BB') ratingMsg = this._t('rating_msg_moderate');
            else ratingMsg = this._t('rating_msg_insufficient');

            var from = this._t('summary_from');
            var totalInvest = ds.totalEnvInvest + ds.totalSocialInvest + ds.totalGovInvest;
            var events = ds.eventLog || [];
            var mitigated = events.filter(function(e) { return e.mitigated; }).length;

            var html = '';
            html += '<p><strong>' + this._t('summary_composite') + '</strong> ' + ds.composite + '/100 (' + from + ' ' + START.composite + ')</p>';
            html += '<p><strong>' + this._t('summary_msci') + '</strong> ' + ds.msciRating + ' (' + from + ' ' + START.rating + ') - ' + ratingMsg + '</p>';
            html += '<p><strong>' + this._t('summary_ebitda') + '</strong> ' + ds.ebitdaMargin + '% (' + from + ' ' + START.ebitda + '%)</p>';
            html += '<hr>';
            html += '<p><strong>' + this._t('summary_escore') + '</strong> ' + Math.round(ds.envScore) + ' (+' + envGain + ')</p>';
            html += '<p><strong>' + this._t('summary_sscore') + '</strong> ' + Math.round(ds.socialScore) + ' (+' + socGain + ')</p>';
            html += '<p><strong>' + this._t('summary_gscore') + '</strong> ' + Math.round(ds.govScore) + ' (+' + govGain + ')</p>';
            html += '<hr>';
            html += '<p><strong>' + this._t('summary_total_invest') + '</strong> $' + totalInvest + 'M';
            html += ' (' + this._t('word_env') + ': $' + ds.totalEnvInvest + 'M | ' + this._t('word_social') + ': $' + ds.totalSocialInvest + 'M | ' + this._t('word_gov') + ': $' + ds.totalGovInvest + 'M)</p>';
            html += '<p><strong>' + this._t('summary_events') + '</strong> ' + this._t('summary_events_detail', { total: events.length, mitigated: mitigated }) + '</p>';

            content.innerHTML = html;
            panel.style.display = 'block';
        }

