        getPerformanceSummary(history) {
            if (!history || history.length === 0) return { totalPeriods: 0 };

            var last = history[history.length - 1];
            var results = last.results || {};
            var composite = results.composite || 0;
            var msci = results.msciRating || 'CCC';

            var perfKey = 'perf_needs';
            if (composite >= 75) perfKey = 'perf_excellent';
            else if (composite >= 60) perfKey = 'perf_good';
            else if (composite >= 45) perfKey = 'perf_moderate';

            var insightKeys = [];
            if (composite >= 70) insightKeys.push('insight_leader');
            else if (composite >= 50) insightKeys.push('insight_progress');
            else insightKeys.push('insight_underinvested');

            var envTotal = 0; var socTotal = 0; var govTotal = 0;
            history.forEach(function(h) {
                if (h.results) {
                    envTotal += h.results.envInvest || 0;
                    socTotal += h.results.socialInvest || 0;
                    govTotal += h.results.govInvest || 0;
                }
            });

            if (envTotal > socTotal + govTotal) insightKeys.push('insight_env_heavy');
            if (results.ebitdaMargin && results.ebitdaMargin < 10) insightKeys.push('insight_financial_suffered');

            return {
                totalPeriods: history.length,
                composite: composite,
                msciRating: msci,
                performanceKey: perfKey,
                performance: this._t(perfKey),
                insightKeys: insightKeys,
                totalInvestment: envTotal + socTotal + govTotal,
                ebitdaMargin: results.ebitdaMargin || 0,
                message: this._t(insightKeys[0])
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var insights = (summary.insightKeys || []).map(function(k) {
                return '<li>' + self._t(k) + '</li>';
            }).join('');

            var html = ''
                + '<div class="esg-completion text-center p-3">'
                + '<h4>' + this._t('completion_title') + '</h4>'
                + '<p><strong>' + this._t('composite_label') + ':</strong> ' + (summary.composite || 0) + '/100'
                + ' &nbsp; <strong>' + this._t('msci_label') + ':</strong> ' + (summary.msciRating || 'CCC') + '</p>'
                + '<p><strong>' + this._t('completion_performance') + ':</strong> ' + (summary.performance || this._t('perf_needs')) + '</p>'
                + '<p><strong>' + this._t('summary_total_invest') + '</strong> $' + (summary.totalInvestment || 0) + 'M</p>'
                + (insights ? '<hr><p><strong>' + this._t('completion_insights') + '</strong></p><ul class="text-left">' + insights + '</ul>' : '')
                + '<hr><p class="text-muted">' + this._t('completion_thanks') + '</p>'
                + '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            // A missed opportunity is not a crisis — give it its own guidance.
            if (results.eventIsOpportunity && results.eventMitigated === false) {
                return this._t('hint_opportunity_missed');
            }
            if (results.eventMitigated === false) {
                return this._t('hint_crisis');
            }
            if (results.composite > 65) {
                return this._t('hint_strong');
            }
            if (results.ebitdaMargin < 10) {
                return this._t('hint_financial');
            }
            return null;
        }

